import{_ as r,o,c as t,a3 as a}from"./chunks/framework.DBpCFmh2.js";const g=JSON.parse('{"title":"Offscreen Document 剪贴板兼容层","description":"本文件聚焦 MV3 扩展中的 **Offscreen Document 剪贴板兼容层**。","frontmatter":{"title":"Offscreen Document 剪贴板兼容层","description":"本文件聚焦 MV3 扩展中的 **Offscreen Document 剪贴板兼容层**。"},"headers":[],"relativePath":"系统架构设计/Chrome-扩展核心架构/Offscreen-Document-剪贴板兼容层/index.md","filePath":"系统架构设计/Chrome-扩展核心架构/Offscreen-Document-剪贴板兼容层/index.md","lastUpdated":null}'),n={name:"系统架构设计/Chrome-扩展核心架构/Offscreen-Document-剪贴板兼容层/index.md"};function c(l,e,i,s,u,f){return o(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="offscreen-document-剪贴板兼容层" tabindex="-1">Offscreen Document 剪贴板兼容层 <a class="header-anchor" href="#offscreen-document-剪贴板兼容层" aria-label="Permalink to &quot;Offscreen Document 剪贴板兼容层&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json" target="_blank" rel="noreferrer">manifest.json</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.html" target="_blank" rel="noreferrer">src/offscreen/offscreen.html</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js" target="_blank" rel="noreferrer">src/offscreen/offscreen.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js" target="_blank" rel="noreferrer">src/background/tool-executor.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tools/media-tools.js" target="_blank" rel="noreferrer">src/background/tools/media-tools.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/scripts/fix-build.js" target="_blank" rel="noreferrer">scripts/fix-build.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构定位">项目结构定位</a></li><li><a href="#核心组件">核心组件</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#详细组件分析">详细组件分析</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能与资源优化">性能与资源优化</a></li><li><a href="#故障恢复与排错指南">故障恢复与排错指南</a></li><li><a href="#结论">结论</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本文件聚焦 MV3 扩展中的 <strong>Offscreen Document 剪贴板兼容层</strong>。该兼容层解决的是：在 Manifest V3 下，Background Service Worker 和 Content Script 对系统剪贴板的访问受到严格限制；而扩展需要为 AI 工具提供稳定的“复制”“粘贴”“获取选中内容”能力。为此，项目通过一个独立的 Offscreen Document 作为剪贴板操作的安全边界，由 Background Service Worker 按需创建、复用并通信。</p><p>关键设计动机包括：</p><ul><li>MV3 的 Background Service Worker 是短暂进程，不适合长期持有敏感状态或 UI 交互上下文。</li><li>Content Script 运行在网页上下文中，直接读写剪贴板会暴露给页面脚本，存在权限泄露风险。</li><li>Offscreen Document 拥有独立文档上下文，可声明 <code>clipboardRead</code> / <code>clipboardWrite</code> 权限，并通过 <code>chrome.offscreen.createDocument</code> 以 <code>CLIPBOARD</code> 理由申请权限，从而把剪贴板访问收敛到最小可信边界。</li></ul><h2 id="项目结构定位" tabindex="-1">项目结构定位 <a class="header-anchor" href="#项目结构定位" aria-label="Permalink to &quot;项目结构定位&quot;">​</a></h2><p>Offscreen Document 剪贴板兼容层涉及以下代码位置：</p><ul><li>扩展清单中声明 <code>offscreen</code>、<code>clipboardRead</code>、<code>clipboardWrite</code> 权限。</li><li>Background 侧负责检查、创建和复用 Offscreen Document，并封装剪贴板工具调用。</li><li>Offscreen HTML 页面承载最小 DOM，用于兼容旧式 <code>document.execCommand</code> 回退路径。</li><li>Offscreen JS 监听来自 Background 的消息，执行实际的剪贴板读写。</li><li>构建脚本将 offscreen 目录复制到产物目录，并对 ES Module 形式的 offscreen.js 做 IIFE 打包处理。</li></ul><pre class="mermaid">graph TB
A[&quot;扩展清单&lt;br/&gt;manifest.json&quot;] --&gt; B[&quot;Background Service Worker&lt;br/&gt;tool-executor.js&quot;]
B --&gt; C[&quot;Offscreen Document&lt;br/&gt;offscreen.html + offscreen.js&quot;]
B --&gt; D[&quot;媒体工具定义&lt;br/&gt;media-tools.js&quot;]
E[&quot;构建脚本&lt;br/&gt;fix-build.js&quot;] --&gt; C
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L7-L27" target="_blank" rel="noreferrer">manifest.json#L7-L27</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L4881-L5067" target="_blank" rel="noreferrer">src/background/tool-executor.js#L4881-L5067</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.html#L1-L12" target="_blank" rel="noreferrer">src/offscreen/offscreen.html#L1-L12</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js#L1-L68" target="_blank" rel="noreferrer">src/offscreen/offscreen.js#L1-L68</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tools/media-tools.js#L29-L49" target="_blank" rel="noreferrer">src/background/tools/media-tools.js#L29-L49</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/scripts/fix-build.js#L355-L394" target="_blank" rel="noreferrer">scripts/fix-build.js#L355-L394</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L7-L27" target="_blank" rel="noreferrer">manifest.json#L7-L27</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L4881-L5067" target="_blank" rel="noreferrer">src/background/tool-executor.js#L4881-L5067</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.html#L1-L12" target="_blank" rel="noreferrer">src/offscreen/offscreen.html#L1-L12</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js#L1-L68" target="_blank" rel="noreferrer">src/offscreen/offscreen.js#L1-L68</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tools/media-tools.js#L29-L49" target="_blank" rel="noreferrer">src/background/tools/media-tools.js#L29-L49</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/scripts/fix-build.js#L355-L394" target="_blank" rel="noreferrer">scripts/fix-build.js#L355-L394</a></li></ul><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><p>本节从职责角度拆解兼容层的核心部分。</p><h3 id="background-剪贴板协调器" tabindex="-1">Background 剪贴板协调器 <a class="header-anchor" href="#background-剪贴板协调器" aria-label="Permalink to &quot;Background 剪贴板协调器&quot;">​</a></h3><p>Background 侧承担以下职责：</p><ul><li>维护 Offscreen Document 生命周期：检测是否存在、避免重复创建、并发等待创建完成。</li><li>将 AI 工具调用转换为 Offscreen Document 消息。</li><li>统一返回结构化结果，包含成功标志、用户可读消息或错误信息。</li><li>对 <code>get_selected</code> 走 Content Script 路径，因为选中文本属于页面上下文，不属于系统剪贴板。</li></ul><p>关键实现要点：</p><ul><li>使用 <code>chrome.runtime.getContexts</code> 查询是否已有目标 Offscreen Document。</li><li>使用 <code>creatingOffscreenDocument</code> 变量防止并发重复创建。</li><li>使用 <code>chrome.offscreen.createDocument</code> 并以 <code>reasons: [&#39;CLIPBOARD&#39;]</code> 声明用途。</li><li>通过 <code>chrome.runtime.sendMessage</code> 向 Offscreen Document 发送 <code>COPY_TO_CLIPBOARD</code> 或 <code>PASTE_FROM_CLIPBOARD</code> 消息。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L4881-L4912" target="_blank" rel="noreferrer">src/background/tool-executor.js#L4881-L4912</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L4997-L5067" target="_blank" rel="noreferrer">src/background/tool-executor.js#L4997-L5067</a></li></ul><h3 id="offscreen-document-剪贴板处理器" tabindex="-1">Offscreen Document 剪贴板处理器 <a class="header-anchor" href="#offscreen-document-剪贴板处理器" aria-label="Permalink to &quot;Offscreen Document 剪贴板处理器&quot;">​</a></h3><p>Offscreen Document 承担实际剪贴板操作：</p><ul><li>注册国际化文案，使失败提示具备多语言支持。</li><li>监听 <code>chrome.runtime.onMessage</code>，根据消息类型分发到复制或粘贴逻辑。</li><li>优先使用现代 <code>navigator.clipboard</code> API。</li><li>当现代 API 失败时，回退到隐藏 <code>&lt;textarea&gt;</code> 配合 <code>document.execCommand(&#39;copy&#39; | &#39;paste&#39;)</code> 的兼容路径。</li><li>始终返回 <code>{ success, message? | text? | error? }</code> 结构，便于 Background 统一处理。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js#L1-L68" target="_blank" rel="noreferrer">src/offscreen/offscreen.js#L1-L68</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.html#L7-L9" target="_blank" rel="noreferrer">src/offscreen/offscreen.html#L7-L9</a></li></ul><h3 id="媒体工具定义" tabindex="-1">媒体工具定义 <a class="header-anchor" href="#媒体工具定义" aria-label="Permalink to &quot;媒体工具定义&quot;">​</a></h3><p><code>media-tools.js</code> 对外暴露 <code>clipboard</code> 工具定义，供 Agent 工具调度系统识别和执行。其参数契约包括：</p><ul><li><code>action</code>：<code>copy</code>、<code>paste</code>、<code>get_selected</code>。</li><li><code>text</code>：复制时需要。</li><li><code>format</code>：获取选中内容时可选，支持 <code>text</code> 或 <code>html</code>。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tools/media-tools.js#L29-L49" target="_blank" rel="noreferrer">src/background/tools/media-tools.js#L29-L49</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>下图展示 MV3 扩展中剪贴板能力的完整调用链：AI 工具 → Background 工具执行器 → Offscreen Document → 系统剪贴板。</p><pre class="mermaid">sequenceDiagram
participant User as &quot;用户&quot;
participant Agent as &quot;Agent 工具调度&quot;
participant BG as &quot;Background 工具执行器&quot;
participant OS as &quot;Offscreen Document&quot;
participant Clipboard as &quot;系统剪贴板&quot;
User-&gt;&gt;Agent : 触发复制/粘贴工具
Agent-&gt;&gt;BG : 调用 clipboard 工具
BG-&gt;&gt;BG : ensureOffscreenDocument()
BG-&gt;&gt;OS : sendMessage(COPY_TO_CLIPBOARD 或 PASTE_FROM_CLIPBOARD)
OS-&gt;&gt;Clipboard : navigator.clipboard.writeText/readText
alt 现代 API 成功
Clipboard--&gt;&gt;OS : 成功
OS--&gt;&gt;BG : { success, message|text }
BG--&gt;&gt;Agent : 工具结果
else 现代 API 失败
OS-&gt;&gt;OS : 回退 textarea + execCommand
OS--&gt;&gt;BG : { success|error }
BG--&gt;&gt;Agent : 工具结果
end
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L4997-L5067" target="_blank" rel="noreferrer">src/background/tool-executor.js#L4997-L5067</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js#L18-L67" target="_blank" rel="noreferrer">src/offscreen/offscreen.js#L18-L67</a></li></ul><h2 id="详细组件分析" tabindex="-1">详细组件分析 <a class="header-anchor" href="#详细组件分析" aria-label="Permalink to &quot;详细组件分析&quot;">​</a></h2><h3 id="offscreen-document-生命周期管理" tabindex="-1">Offscreen Document 生命周期管理 <a class="header-anchor" href="#offscreen-document-生命周期管理" aria-label="Permalink to &quot;Offscreen Document 生命周期管理&quot;">​</a></h3><p>Background 侧的 <code>ensureOffscreenDocument</code> 是生命周期控制入口。其行为可概括为：</p><ol><li>计算 Offscreen Document URL。</li><li>查询当前已存在的 OFFSCREEN_DOCUMENT 上下文。</li><li>若已存在，直接返回。</li><li>若正在创建，则等待已有 Promise。</li><li>否则发起 <code>chrome.offscreen.createDocument</code>，并使用 finally 清理创建锁。</li></ol><pre class="mermaid">flowchart TD
Start([&quot;进入 ensureOffscreenDocument&quot;]) --&gt; CheckExisting[&quot;查询现有 Offscreen Document&quot;]
CheckExisting --&gt; Exists{&quot;已存在?&quot;}
Exists --&gt; |是| ReturnOK[&quot;直接返回&quot;]
Exists --&gt; |否| HasCreating{&quot;正在创建?&quot;}
HasCreating --&gt; |是| WaitPromise[&quot;等待已有创建 Promise&quot;]
HasCreating --&gt; |否| CreateDoc[&quot;调用 chrome.offscreen.createDocument&quot;]
CreateDoc --&gt; AwaitCreate[&quot;await 创建完成&quot;]
AwaitCreate --&gt; Cleanup[&quot;清理 creatingOffscreenDocument&quot;]
Cleanup --&gt; ReturnOK
WaitPromise --&gt; ReturnOK
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L4885-L4912" target="_blank" rel="noreferrer">src/background/tool-executor.js#L4885-L4912</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L4881-L4912" target="_blank" rel="noreferrer">src/background/tool-executor.js#L4881-L4912</a></li></ul><h3 id="剪贴板读写权限模型" tabindex="-1">剪贴板读写权限模型 <a class="header-anchor" href="#剪贴板读写权限模型" aria-label="Permalink to &quot;剪贴板读写权限模型&quot;">​</a></h3><p>权限模型分为三层：</p><ul><li>扩展清单层：声明 <code>offscreen</code>、<code>clipboardRead</code>、<code>clipboardWrite</code>。</li><li>Chrome 权限层：通过 <code>createDocument</code> 的 <code>reasons: [&#39;CLIPBOARD&#39;]</code> 说明用途。</li><li>运行时层：Offscreen Document 内使用 <code>navigator.clipboard</code> 进行实际读写。</li></ul><pre class="mermaid">flowchart TD
Manifest[&quot;manifest.json&lt;br/&gt;声明 offscreen / clipboardRead / clipboardWrite&quot;] --&gt; BrowserPolicy[&quot;Chrome 权限策略&quot;]
BrowserPolicy --&gt; CreateDoc[&quot;Background 调用 createDocument&lt;br/&gt;reasons: CLIPBOARD&quot;]
CreateDoc --&gt; OffscreenContext[&quot;Offscreen Document 上下文&quot;]
OffscreenContext --&gt; NavigatorClipboard[&quot;navigator.clipboard API&quot;]
NavigatorClipboard --&gt; SystemClipboard[&quot;系统剪贴板&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L7-L27" target="_blank" rel="noreferrer">manifest.json#L7-L27</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L4901-L4905" target="_blank" rel="noreferrer">src/background/tool-executor.js#L4901-L4905</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js#L18-L67" target="_blank" rel="noreferrer">src/offscreen/offscreen.js#L18-L67</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L7-L27" target="_blank" rel="noreferrer">manifest.json#L7-L27</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L4901-L4905" target="_blank" rel="noreferrer">src/background/tool-executor.js#L4901-L4905</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js#L18-L67" target="_blank" rel="noreferrer">src/offscreen/offscreen.js#L18-L67</a></li></ul><h3 id="剪贴板操作封装接口" tabindex="-1">剪贴板操作封装接口 <a class="header-anchor" href="#剪贴板操作封装接口" aria-label="Permalink to &quot;剪贴板操作封装接口&quot;">​</a></h3><p>Background 侧暴露两个主要导出函数：</p><ul><li><code>executeCopyToClipboard(args, toolCallId)</code></li><li><code>executePasteFromClipboard(args, toolCallId)</code></li></ul><p>它们共同遵循以下流程：</p><ol><li>校验必要参数（例如复制时必须提供文本）。</li><li>确保 Offscreen Document 可用。</li><li>发送消息到 Offscreen Document。</li><li>解析响应并包装为标准工具结果。</li></ol><pre class="mermaid">flowchart TD
Entry([&quot;executeCopyToClipboard / executePasteFromClipboard&quot;]) --&gt; Validate[&quot;参数校验&quot;]
Validate --&gt; EnsureOS[&quot;ensureOffscreenDocument()&quot;]
EnsureOS --&gt; SendMsg[&quot;chrome.runtime.sendMessage&quot;]
SendMsg --&gt; ParseResp[&quot;解析 response.success / error / text&quot;]
ParseResp --&gt; WrapResult[&quot;包装为工具结果&quot;]
WrapResult --&gt; Exit([&quot;返回给上层工具调度&quot;])
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L5031-L5067" target="_blank" rel="noreferrer">src/background/tool-executor.js#L5031-L5067</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L4997-L5067" target="_blank" rel="noreferrer">src/background/tool-executor.js#L4997-L5067</a></li></ul><h3 id="offscreen-document-内部处理流程" tabindex="-1">Offscreen Document 内部处理流程 <a class="header-anchor" href="#offscreen-document-内部处理流程" aria-label="Permalink to &quot;Offscreen Document 内部处理流程&quot;">​</a></h3><p>Offscreen Document 内部对复制和粘贴分别实现主路径与回退路径。</p><h4 id="复制流程" tabindex="-1">复制流程 <a class="header-anchor" href="#复制流程" aria-label="Permalink to &quot;复制流程&quot;">​</a></h4><pre class="mermaid">flowchart TD
CopyEntry([&quot;收到 COPY_TO_CLIPBOARD&quot;]) --&gt; TryModern[&quot;尝试 navigator.clipboard.writeText&quot;]
TryModern --&gt; ModernOk{&quot;成功?&quot;}
ModernOk --&gt; |是| RespondSuccess[&quot;返回 success + 成功消息&quot;]
ModernOk --&gt; |否| Fallback[&quot;隐藏 textarea 设置值并 select&quot;]
Fallback --&gt; ExecCopy[&quot;document.execCommand(&#39;copy&#39;)&quot;]
ExecCopy --&gt; CopyOk{&quot;execCommand 成功?&quot;}
CopyOk --&gt; |是| RespondFallbackSuccess[&quot;返回 success + 成功消息&quot;]
CopyOk --&gt; |否| RespondError[&quot;返回 success=false + 错误消息&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js#L18-L41" target="_blank" rel="noreferrer">src/offscreen/offscreen.js#L18-L41</a></li></ul><h4 id="粘贴流程" tabindex="-1">粘贴流程 <a class="header-anchor" href="#粘贴流程" aria-label="Permalink to &quot;粘贴流程&quot;">​</a></h4><pre class="mermaid">flowchart TD
PasteEntry([&quot;收到 PASTE_FROM_CLIPBOARD&quot;]) --&gt; TryRead[&quot;尝试 navigator.clipboard.readText&quot;]
TryRead --&gt; ReadOk{&quot;成功?&quot;}
ReadOk --&gt; |是| RespondText[&quot;返回 success + text&quot;]
ReadOk --&gt; |否| FocusTextarea[&quot;清空并聚焦 textarea&quot;]
FocusTextarea --&gt; ExecPaste[&quot;document.execCommand(&#39;paste&#39;)&quot;]
ExecPaste --&gt; ReadValue[&quot;读取 textarea.value&quot;]
ReadValue --&gt; PasteOk{&quot;成功且有文本?&quot;}
PasteOk --&gt; |是| RespondFallbackText[&quot;返回 success + text&quot;]
PasteOk --&gt; |否| RespondPasteError[&quot;返回 success=false + 错误消息&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js#L43-L67" target="_blank" rel="noreferrer">src/offscreen/offscreen.js#L43-L67</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js#L18-L67" target="_blank" rel="noreferrer">src/offscreen/offscreen.js#L18-L67</a></li></ul><h3 id="为什么不在-content-script-中直接访问剪贴板" tabindex="-1">为什么不在 Content Script 中直接访问剪贴板 <a class="header-anchor" href="#为什么不在-content-script-中直接访问剪贴板" aria-label="Permalink to &quot;为什么不在 Content Script 中直接访问剪贴板&quot;">​</a></h3><p>虽然 Content Script 在某些场景下可以访问 <code>navigator.clipboard</code>，但本项目选择 Offscreen Document 的原因包括：</p><ul><li><strong>权限隔离</strong>：Content Script 与网页共享 DOM 环境，若允许网页脚本间接读取剪贴板，会造成隐私泄露。</li><li><strong>Background 进程约束</strong>：MV3 Background Service Worker 可能被终止，不适合长期持有剪贴板相关状态。</li><li><strong>最小可信边界</strong>：Offscreen Document 是扩展自有页面，可通过清单权限精确控制剪贴板访问范围。</li><li><strong>兼容性兜底</strong>：Offscreen Document 可安全使用 <code>document.execCommand</code> 等旧 API 作为回退，而不污染网页上下文。</li></ul><p>因此，<code>get_selected</code> 仍走 Content Script，因为选中内容是页面级状态；而 <code>copy</code> 和 <code>paste</code> 走 Offscreen Document，因为它们是系统级剪贴板操作。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L4997-L5029" target="_blank" rel="noreferrer">src/background/tool-executor.js#L4997-L5029</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.html#L7-L9" target="_blank" rel="noreferrer">src/offscreen/offscreen.html#L7-L9</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><p>Offscreen Document 剪贴板兼容层的依赖关系如下：</p><pre class="mermaid">graph LR
Manifest[&quot;manifest.json&quot;] --&gt; ToolExecutor[&quot;tool-executor.js&quot;]
MediaTools[&quot;media-tools.js&quot;] --&gt; ToolExecutor
ToolExecutor --&gt; OffscreenHTML[&quot;offscreen.html&quot;]
ToolExecutor --&gt; OffscreenJS[&quot;offscreen.js&quot;]
FixBuild[&quot;fix-build.js&quot;] --&gt; OffscreenDir[&quot;offscreen 目录产物&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L7-L27" target="_blank" rel="noreferrer">manifest.json#L7-L27</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tools/media-tools.js#L29-L49" target="_blank" rel="noreferrer">src/background/tools/media-tools.js#L29-L49</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L4881-L5067" target="_blank" rel="noreferrer">src/background/tool-executor.js#L4881-L5067</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.html#L1-L12" target="_blank" rel="noreferrer">src/offscreen/offscreen.html#L1-L12</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js#L1-L68" target="_blank" rel="noreferrer">src/offscreen/offscreen.js#L1-L68</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/scripts/fix-build.js#L355-L394" target="_blank" rel="noreferrer">scripts/fix-build.js#L355-L394</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/manifest.json#L7-L27" target="_blank" rel="noreferrer">manifest.json#L7-L27</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tools/media-tools.js#L29-L49" target="_blank" rel="noreferrer">src/background/tools/media-tools.js#L29-L49</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L4881-L5067" target="_blank" rel="noreferrer">src/background/tool-executor.js#L4881-L5067</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.html#L1-L12" target="_blank" rel="noreferrer">src/offscreen/offscreen.html#L1-L12</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js#L1-L68" target="_blank" rel="noreferrer">src/offscreen/offscreen.js#L1-L68</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/scripts/fix-build.js#L355-L394" target="_blank" rel="noreferrer">scripts/fix-build.js#L355-L394</a></li></ul><h2 id="性能与资源优化" tabindex="-1">性能与资源优化 <a class="header-anchor" href="#性能与资源优化" aria-label="Permalink to &quot;性能与资源优化&quot;">​</a></h2><p>当前实现已经做了若干基础优化：</p><ul><li><strong>按需创建</strong>：仅在首次需要剪贴板功能时创建 Offscreen Document。</li><li><strong>去重查询</strong>：通过 <code>chrome.runtime.getContexts</code> 判断是否已存在，避免重复创建。</li><li><strong>并发保护</strong>：使用 <code>creatingOffscreenDocument</code> 变量防止多个调用同时创建。</li><li><strong>轻量 DOM</strong>：Offscreen HTML 仅包含一个隐藏 textarea，不加载重型 UI。</li><li><strong>IIFE 打包</strong>：构建脚本将 offscreen.js 打包为 IIFE，减少模块加载开销。</li></ul><p>可进一步优化的方向：</p><ul><li><strong>显式销毁</strong>：当前未看到主动销毁 Offscreen Document 的逻辑；可在长时间无剪贴板操作后考虑关闭空闲上下文。</li><li><strong>消息队列</strong>：若未来出现高频剪贴板请求，可增加队列合并与节流。</li><li><strong>错误重试上限</strong>：对反复失败的剪贴板操作增加降级策略，避免无限重试。</li><li><strong>日志采样</strong>：频繁复制粘贴场景下建议降低调试日志频率。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L4881-L4912" target="_blank" rel="noreferrer">src/background/tool-executor.js#L4881-L4912</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.html#L7-L9" target="_blank" rel="noreferrer">src/offscreen/offscreen.html#L7-L9</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/scripts/fix-build.js#L355-L394" target="_blank" rel="noreferrer">scripts/fix-build.js#L355-L394</a></li></ul><h2 id="故障恢复与排错指南" tabindex="-1">故障恢复与排错指南 <a class="header-anchor" href="#故障恢复与排错指南" aria-label="Permalink to &quot;故障恢复与排错指南&quot;">​</a></h2><h3 id="常见问题与定位思路" tabindex="-1">常见问题与定位思路 <a class="header-anchor" href="#常见问题与定位思路" aria-label="Permalink to &quot;常见问题与定位思路&quot;">​</a></h3><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>排查建议</th></tr></thead><tbody><tr><td>复制失败</td><td>Offscreen Document 未创建或权限不足</td><td>检查 manifest 是否声明 <code>offscreen</code>、<code>clipboardWrite</code>；确认 <code>createDocument</code> 是否成功</td></tr><tr><td>粘贴失败</td><td>浏览器不允许读取剪贴板或用户未授权</td><td>检查 manifest 是否声明 <code>clipboardRead</code>；查看 Offscreen 回退路径是否被触发</td></tr><tr><td>工具调用无响应</td><td>Background 与 Offscreen 消息通道异常</td><td>检查 <code>chrome.runtime.sendMessage</code> 是否返回；确认 Offscreen 监听器是否注册</td></tr><tr><td>构建后 Offscreen 不可用</td><td>offscreen 目录未被正确复制或打包</td><td>检查 fix-build.js 是否复制 offscreen 目录并打包 offscreen.js</td></tr></tbody></table><h3 id="错误处理机制" tabindex="-1">错误处理机制 <a class="header-anchor" href="#错误处理机制" aria-label="Permalink to &quot;错误处理机制&quot;">​</a></h3><ul><li>Background 层捕获异常并返回结构化错误，避免上层工具调度崩溃。</li><li>Offscreen 层先尝试现代 API，失败后进入回退路径，再失败则返回明确错误消息。</li><li>所有错误消息均经过 i18n 处理，便于用户理解。</li></ul><pre class="mermaid">flowchart TD
Call[&quot;工具调用&quot;] --&gt; BGTry[&quot;Background 调用 try/catch&quot;]
BGTry --&gt; OSTry[&quot;Offscreen 调用 try/catch&quot;]
OSTry --&gt; ModernAPI[&quot;navigator.clipboard&quot;]
ModernAPI --&gt; Fallback[&quot;textarea + execCommand&quot;]
Fallback --&gt; ErrorReturn[&quot;返回 success=false + error&quot;]
ModernAPI --&gt; SuccessReturn[&quot;返回 success=true + data&quot;]
ErrorReturn --&gt; BGWrap[&quot;Background 包装错误&quot;]
SuccessReturn --&gt; BGWrap
BGWrap --&gt; Result[&quot;返回工具结果&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L5031-L5067" target="_blank" rel="noreferrer">src/background/tool-executor.js#L5031-L5067</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js#L18-L67" target="_blank" rel="noreferrer">src/offscreen/offscreen.js#L18-L67</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L5031-L5067" target="_blank" rel="noreferrer">src/background/tool-executor.js#L5031-L5067</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js#L18-L67" target="_blank" rel="noreferrer">src/offscreen/offscreen.js#L18-L67</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>Offscreen Document 剪贴板兼容层在本项目中承担了 MV3 环境下剪贴板访问的关键桥接职责。它通过 Background 侧的生命周期管理和 Offscreen 侧的最小化剪贴板处理器，实现了：</p><ul><li>安全的权限边界：剪贴板访问集中在扩展自有页面。</li><li>可靠的兼容性：现代 API 失败时可回退到旧式命令。</li><li>清晰的职责分离：Background 负责协调，Offscreen 负责执行。</li><li>可扩展的工具契约：通过 <code>media-tools.js</code> 暴露统一的 clipboard 工具定义。</li></ul><p>未来若扩展更多敏感系统能力，可沿用该模式：将高风险操作收敛到 Offscreen Document，并由 Background 统一编排、鉴权和监控。</p>`,113)])])}const d=r(n,[["render",c]]);export{g as __pageData,d as default};
